contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, uint256 mintedAmount) public {
        require(target != address(0));

        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeTargetBal = c.balanceOf(target); if (__ESBMC_reverted()) return;

        c.mintToken(target, mintedAmount); if (__ESBMC_reverted()) return;

        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterTargetBal = c.balanceOf(target); if (__ESBMC_reverted()) return;

        assert(afterTotal - beforeTotal == mintedAmount && afterTargetBal - beforeTargetBal == mintedAmount);
    }
}

