    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, uint256 mintedAmount) internal {
        vm.assume(target != address(0));
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        uint256 beforeTargetBal;
        try c.balanceOf(target) returns (uint256 __r) { beforeTargetBal = __r; } catch { return; }
        try c.mintToken(target, mintedAmount) {} catch { return; }
        uint256 afterTotal;
        try c.totalSupply() returns (uint256 __r) { afterTotal = __r; } catch { return; }
